#!/usr/bin/env node
/**
 * verify-update-prerequisites.cjs
 *
 * Regression gate for the console rolling-upgrade chain, anchored on two field
 * incidents (2026-09-24, site 192.168.102.152-154):
 *
 *  1. P0 — update.json generated by the installer pointed ssh_key at
 *     /etc/clusterguard/ssh/controller_ed25519, which the runtime owns as
 *     clusterguard:clusterguard 0600. The update job validates privileged
 *     inputs via `workspace check-file` (root ownership required), so every
 *     console-initiated execution died before touching a node. The installer
 *     must now create a root:root 0600 copy under /etc/clusterguard/updates
 *     and point ssh_key at that copy.
 *
 *  2. Helper first-start flake — clusterguard-update-helper.service used
 *     RuntimeDirectory=clusterguard for a directory shared with the rest of
 *     the runtime; first start raced into exit 233/RUNTIME_DIRECTORY and any
 *     stop would remove the shared directory. The unit must create the
 *     directory idempotently via ExecStartPre and must NOT claim
 *     RuntimeDirectory.
 *
 *  3. P0 reboot outage (2026-09-28) — the same ExecStartPre created that shared
 *     /run/clusterguard as 0750, and the managed MySQL/PostgreSQL units nest
 *     their RuntimeDirectory below it as unprivileged users outside the
 *     clusterguard group. /run is a tmpfs, so the helper won the boot race and
 *     every reboot stranded the cluster. The unit must create it 0755, and this
 *     gate must not accept 0750 as an alternative — its earlier revision did,
 *     which is exactly how the defect survived a full gate suite.
 *
 * Run: node tools/verify-update-prerequisites.cjs [--repo <path>]
 */
'use strict';

const fs = require('fs');
const path = require('path');

const repo = (() => {
  const flag = process.argv.indexOf('--repo');
  if (flag !== -1 && process.argv[flag + 1]) return process.argv[flag + 1];
  return path.resolve(__dirname, '..');
})();

const read = (relative) => {
  const file = path.join(repo, relative);
  if (!fs.existsSync(file)) throw new Error(`missing file: ${relative}`);
  return fs.readFileSync(file, 'utf8');
};

const failures = [];
const check = (name, ok, detail) => {
  if (ok) {
    console.log(`ok   ${name}`);
  } else {
    failures.push(name);
    console.error(`FAIL ${name}${detail ? ` — ${detail}` : ''}`);
  }
};

const installer = read('scripts/install_clusterguard.sh');
const helperUnit = read('packaging/systemd/clusterguard-update-helper.service');
const job = read('scripts/clusterguard-update-job.sh');
const workspace = read('internal/platformupdate/workspace_unix.go');

// --- Gate 1: installer emits a root-owned ssh key copy -------------------
check(
  'installer: update.json ssh_key points at /etc/clusterguard/updates/controller_ed25519',
  installer.includes('ssh_key:"/etc/clusterguard/updates/controller_ed25519"'),
);
check(
  'installer: creates root:root 0600 copy of controller_ed25519',
  /install -m 0600 -o root -g root \/etc\/clusterguard\/ssh\/controller_ed25519 \/etc\/clusterguard\/updates\/controller_ed25519/.test(installer),
);
check(
  'installer: creates /etc/clusterguard/updates directory root:root 0750',
  /install -d -m 0750 -o root -g root \/etc\/clusterguard\/updates/.test(installer),
);
check(
  'installer: does NOT point ssh_key at the clusterguard-owned key anymore',
  !installer.includes('ssh_key:"/etc/clusterguard/ssh/controller_ed25519"'),
);

// --- Gate 2: helper unit must not own the shared runtime directory -------
check(
  'helper unit: no RuntimeDirectory=clusterguard',
  !/^RuntimeDirectory=/m.test(helperUnit),
  'RuntimeDirectory on a shared dir re-chowns it per start (233 race) and deletes it on stop',
);
check(
  'helper unit: idempotent ExecStartPre creates a world-traversable /run/clusterguard',
  /ExecStartPre=.*install -d -m 0755 -o root -g clusterguard \/run\/clusterguard/.test(helperUnit),
  'the managed engine units nest their own RuntimeDirectory below this path and run as mysql/postgres, which are not members of the clusterguard group',
);
// On 2026-09-28 this very check pinned 0750 and kept passing while the site sat
// in a reboot-length outage: /run is a tmpfs, the helper wins the boot race, and
// mysqld then cannot traverse its own parent and aborts with "Could not create
// unix socket lock file" (restart counters reached 2063/2069/2072). A gate that
// accepts the defect's mode is not a gate, so its absence is pinned separately
// rather than left implied by the 0755 pattern above.
check(
  'helper unit: does NOT create /run/clusterguard 0750',
  !/ExecStartPre=.*install -d -m 0750\b[^\n]*\/run\/clusterguard/.test(helperUnit),
  '0750 on the shared parent blocks the unprivileged engine users from reaching their own sockets',
);
check(
  'helper unit: socket path unchanged (/run/clusterguard/update-helper.sock)',
  helperUnit.includes('--socket /run/clusterguard/update-helper.sock'),
);

// --- Gate 3: the consuming side still enforces root ownership ------------
check(
  'update job: privileged inputs still validated via workspace check-file',
  /workspace check-file "\$\{privileged_input\}"/.test(job) && job.includes('ssh_key'),
);
check(
  'workspace_unix: root ownership requirement still in force',
  workspace.includes('stat.Uid != 0') && workspace.includes('privileged input must be root-owned'),
);

if (failures.length) {
  console.error(`\n${failures.length} check(s) failed.`);
  process.exit(1);
}
console.log('\nall update-prerequisite checks passed.');
